{
  "name": "opencode-explained-right",
  "version": "0.1.0",
  "type": "module",
  "description": "OpenCode plugin: makes the agent verbally state why it wants to access files outside the project before it does.",
  "license": "MIT",
  "main": "./explained-right.ts",
  "exports": {
    ".": {
      "types": "./explained-right.ts",
      "import": "./explained-right.ts"
    },
    "./server": {
      "types": "./explained-right.ts",
      "import": "./explained-right.ts"
    }
  },
  "files": [
    "explained-right.ts",
    "README.md",
    "README.zh-CN.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "permission",
    "external-directory",
    "guardrail",
    "security"
  ],
  "repository": {
    "type": "git",
    "url": "https://github.com/Ryan9438/opencode-explained-right"
  },
  "engines": {
    "opencode": ">=1.17.0"
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "install:global": "bash scripts/install.sh"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.13",
    "@types/bun": "^1.2.0",
    "typescript": "^5.5.0"
  }
}
